public class Solution{public bool IsAdditiveNumber(string s){int n=s.Length;for(int i=1;i<n;i++){if(s[0]=='0'&&i>1)break;for(int j=i+1;j<n;j++){if(s[i]=='0'&&j-i>1)break;if(!ulong.TryParse(s.Substring(0,i),out var a)||!ulong.TryParse(s.Substring(i,j-i),out var b))continue;int p=j;while(p<n){ulong c=a+b;string x=c.ToString();if(!s.Substring(p).StartsWith(x))break;p+=x.Length;a=b;b=c;}if(p==n)return true;}}return false;}}
